{
  "technical_and_design_decisions": [
    "Use the existing Spring XD Gradle build system; make it cross-platform by replacing Unix-only scripts with Gradle tasks or portable scripts.",
    "Implement Spark Streaming support as standard Spring XD modules (source/processor/sink) using Java Lambdas for APIs and Scala for Spark-specific logic.",
    "For Kafka upgrade, first backport XD's Kafka enhancements to the Spring Integration Kafka (SI Kafka) project, then depend on the SI Kafka GA release.",
    "Provide migration assistance for 1.0 to 1.1 as a written guide plus ported sample modules rather than a fully automated migration tool.",
    "Provision Windows test environment on AWS EC2 using a standard Windows Server image and install required dependencies (JDK, Hadoop, etc.); set up a Jenkins CI job for acceptance tests.",
    "Update copyright in the reference guide source (AsciiDoc/DocBook) and regenerate the PDF as part of the build."
  ],
  "assumptions": [
    "The Spring XD version targeted is 1.1, developed with Java 8 (the Spring Framework 6/Java 17 text in the spec is background and not applied to this older XD release).",
    "Existing Spring XD source code, test suites, and documentation sources are available and baseline builds succeed on Linux.",
    "The developer has access to AWS EC2 and a Jenkins CI server, and can provision Windows images.",
    "Spring Integration Kafka and Spring Hadoop (SHDP) GA releases are available in public repositories.",
    "Acceptance tests already exist and can be run with reasonable effort on Windows after environment setup.",
    "Effort estimates cover coding, unit/integration testing, and basic verification by a single experienced developer, excluding unrelated production support.",
    "Pig and Spark Streaming samples are for demonstration and use existing XD extension points."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "Analyze 1.0 to 1.1 migration impact",
      "activity_description": "Review Spring XD 1.0 to 1.1 changes, API breaks, and assess impact on custom modules and data pipelines.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A02",
      "activity_name": "Create migration guide and tooling",
      "activity_description": "Produce documentation and/or simple scripts to help users port custom modules from XD 1.0 to 1.1.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A03",
      "activity_name": "Port reference custom modules",
      "activity_description": "Port sample custom modules to XD 1.1 and verify existing data pipelines operate correctly.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A04",
      "activity_name": "Create Pig script/job sample",
      "activity_description": "Develop a reference Pig script/job and integrate it as a sample in XD to demonstrate Pig job usage.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A05",
      "activity_name": "Enable Windows build",
      "activity_description": "Modify build scripts and configuration so XD can be built on a Windows machine, fixing path and environment issues.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A06",
      "activity_name": "Provision Windows EC2 image",
      "activity_description": "Provision a Windows EC2 instance with required dependencies to run XD acceptance tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A07",
      "activity_name": "Run acceptance tests on Windows",
      "activity_description": "Execute the acceptance test suite on the Windows environment, diagnose and fix failures.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A08",
      "activity_name": "Set up Windows CI build",
      "activity_description": "Create a CI build job (e.g., Jenkins) that provisions/runs acceptance tests on Windows.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A09",
      "activity_name": "Implement Spark Streaming processors",
      "activity_description": "Design and implement Spark Streaming data processor modules in XD using Java Lambdas and Scala.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A10",
      "activity_name": "Test Spark Streaming integration",
      "activity_description": "Write unit/integration tests and a sample for the Spark Streaming processors, verifying functionality.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Update reference guide copyright",
      "activity_description": "Update copyright year from 2014 to 2015 in the reference guide source and verify PDF generation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A12",
      "activity_name": "Backport Kafka changes to SI Kafka",
      "activity_description": "Extract and backport XD-specific Kafka changes into the Spring Integration Kafka project.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A13",
      "activity_name": "Upgrade to Kafka SI GA",
      "activity_description": "Upgrade XD dependency to Spring Integration Kafka GA, adapt code, and test integration.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A14",
      "activity_name": "Upgrade to SHDP GA",
      "activity_description": "Upgrade XD dependency to Spring Hadoop (SHDP) GA, adapt code, and test integration.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A15",
      "activity_name": "Integration testing and release prep",
      "activity_description": "Perform overall integration testing of all new features and upgrades, and prepare the increment for release.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 372
  }
}

